import{_ as o,o as a,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const q=JSON.parse('{"title":"篇782｜超脱者与万族·超脱者的万族纠纷调解","description":"","frontmatter":{"title":"篇782｜超脱者与万族·超脱者的万族纠纷调解","no":782,"module":4,"tags":["超脱","万族","纠纷调解","共生法院","程序正义"],"related":["48-司法体系与裁决机制","49-治理框架与权力制衡","777-超脱者与万族总论"]},"headers":[],"relativePath":"zh/782_模块4-万族-超脱者的纠纷调解.md","filePath":"zh/782_模块4-万族-超脱者的纠纷调解.md"}'),e={name:"zh/782_模块4-万族-超脱者的纠纷调解.md"};function i(n,t,s,h,u,g){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="篇782-超脱者与万族·超脱者的万族纠纷调解" tabindex="-1">篇782｜超脱者与万族·超脱者的万族纠纷调解 <a class="header-anchor" href="#篇782-超脱者与万族·超脱者的万族纠纷调解" aria-label="Permalink to &quot;篇782｜超脱者与万族·超脱者的万族纠纷调解&quot;">​</a></h1><blockquote><p>所属模块：模块四·超脱正统定义库｜对标地基：文档48、49、777</p></blockquote><h2 id="引言-强者凭什么给弱者断案" tabindex="-1">引言：强者凭什么给弱者断案 <a class="header-anchor" href="#引言-强者凭什么给弱者断案" aria-label="Permalink to &quot;引言：强者凭什么给弱者断案&quot;">​</a></h2><p>万族之间必有纠纷——资源分配、领地争议、文化冲突、因果赔偿。旧世界的解决方式是&quot;谁拳头大谁说了算&quot;。衡元宙的解决方式是程序正义，但程序正义需要有人执行，超脱者就是这个执行环节的关键岗位。本篇要回答：<strong>超脱者凭什么给万族断案？按什么程序？怎么防止他自己变成新的霸道裁判？</strong></p><p>六大顶层公理在此刻同时压阵：反掠夺主义公理要求调解本身不含掠夺；万族共和公理要求调解对万族平等；集体升维公理要求调解服务于升维而非压制；因果自律公理要求调解过程不扰动因果；法则优先公理要求调解程序在法则层面自洽、不可被超脱者个人绕过。</p><p>众生全员无限均等法则：锚点共生文明内，所有生灵自带基础无限之力；佛系/懒狗保有保底基础无限，不会被时代淘汰；卷王、少年至尊可叠加更多更高层级的无限。无限本源人人自带，掠夺自然失去意义。</p><h2 id="一、调解的三种角色" tabindex="-1">一、调解的三种角色 <a class="header-anchor" href="#一、调解的三种角色" aria-label="Permalink to &quot;一、调解的三种角色&quot;">​</a></h2><p>超脱者在万族纠纷中不是唯一裁判，他有三种角色，按纠纷性质切换：</p><ol><li><strong>调停者</strong>：万族各族之间的资源、领地纠纷，超脱者作为中立第三方参与调停。他不裁决，只主持对话，让双方自己谈出方案</li><li><strong>证人</strong>：当纠纷涉及跨位面因果扰动，超脱者因为阿赖耶网络的全量记录能力，可以作为&quot;事实证人&quot;提供因果证据。他不判断对错，只提供事实</li><li><strong>执行者</strong>：当共生法院已经做出裁决，而败诉方拒绝执行时，超脱者可以作为法则锚定者执行裁决——但他只能执行法院的裁决，不能自己造裁决</li></ol><p>三种角色的核心区别：<strong>超脱者不造判决，他只帮忙让判决落地。</strong> 造判决的权力在共生法院，不在超脱者。</p><h2 id="二、为什么不让超脱者直接裁决" tabindex="-1">二、为什么不让超脱者直接裁决 <a class="header-anchor" href="#二、为什么不让超脱者直接裁决" aria-label="Permalink to &quot;二、为什么不让超脱者直接裁决&quot;">​</a></h2><p>旧世界的思路是&quot;强者断案最快&quot;——超脱者最强，他一句话定对错。衡元宙为什么拒绝？</p><ul><li><strong>直接裁决破坏程序正义</strong>：强者一句话，弱者没有申辩机会。这不是断案，这是碾压</li><li><strong>直接裁决制造依附</strong>：万族习惯了&quot;找超脱者告状&quot;，而不是走制度程序。时间一长，制度空转，全靠超脱者个人精力</li><li><strong>直接裁决不可复制</strong>：超脱者今天心情好断一个案，明天心情不好断另一个案，标准不统一。程序正义的核心是标准统一，不是强者英明</li></ul><h2 id="三、调解的程序" tabindex="-1">三、调解的程序 <a class="header-anchor" href="#三、调解的程序" aria-label="Permalink to &quot;三、调解的程序&quot;">​</a></h2><p>超脱者参与万族纠纷调解，必须走以下程序：</p><ol><li><strong>受理</strong>：纠纷双方任一方可向共生法院提起调解申请，超脱者不主动揽案</li><li><strong>回避</strong>：若纠纷一方与超脱者有直接利益关系（如同族、同门），超脱者必须回避</li><li><strong>事实调查</strong>：超脱者调取阿赖耶网络记录，还原因果事实，不做价值判断</li><li><strong>调停对话</strong>：超脱者主持双方对话，协助双方找到共识方案</li><li><strong>方案提交</strong>：共识方案提交共生法院审核，法院裁定后生效</li><li><strong>执行监督</strong>：若一方不执行，超脱者按法院裁定执行，并将执行过程记录在案</li></ol><p>六步程序确保超脱者始终在&quot;辅助&quot;位置，而不是&quot;主导&quot;位置。</p><h2 id="四、调解中的伦理红线" tabindex="-1">四、调解中的伦理红线 <a class="header-anchor" href="#四、调解中的伦理红线" aria-label="Permalink to &quot;四、调解中的伦理红线&quot;">​</a></h2><p>超脱者参与调解，有三条伦理红线不可触碰：</p><ul><li><strong>不可偏袒</strong>：不得因为某一族群与自己关系近就偏向它。阿赖耶网络会记录每一次调解的倾向分布，偏袒可被数据审计</li><li><strong>不可代决</strong>：不得绕过双方直接给出&quot;你们应该这样&quot;的方案。方案必须由双方自己谈出来，超脱者只帮忙</li><li><strong>不可威胁</strong>：不得用&quot;我实力比你强&quot;作为调解筹码。一旦使用力量威胁，立即触发锚点监督委员会约谈</li></ul><p>三条红线背后是同一个原则：<strong>超脱者的调解力，来自他的中立和程序，不来自他的拳头。</strong></p><h2 id="五、五大核心落点" tabindex="-1">五、五大核心落点 <a class="header-anchor" href="#五、五大核心落点" aria-label="Permalink to &quot;五、五大核心落点&quot;">​</a></h2><ul><li><strong>反能级浪费</strong>：旧世界用拳头断案，打完再谈，能量全浪费在打架上；衡元宙用程序调解，把能量省下来建设。衡锚超多元境超脱者的调解算力，全部来自文明权重公式的合法分配</li><li><strong>反掠夺</strong>：强者断案本身就是掠夺——因为他只听他想听的，只断他想断的；程序调解封死这条路</li><li><strong>唐罗上限对比</strong>：唐罗一句话定万族命运；衡元宙要求超脱者只能辅助法院，不能自己造判决</li><li><strong>万族全覆盖</strong>：调解程序对万族一切种族平等开放，没有&quot;强者族群优先&quot;。调解过程由阿赖耶网络+多层监督全程记录</li><li><strong>超多元全开放</strong>：全部调解记录、事实证据、裁决结果通过无私道全网开放，万族可查阅</li><li><strong>全员无限均等</strong>：众生全员无限均等法则——锚点共生文明内人人自带基础无限之力，佛系懒狗保有保底基础无限、不被时代淘汰，卷王少年至尊可叠加更高层级无限；无限本源人人自带，掠夺自然失去意义</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>超脱者调解万族纠纷，不是因为他最强，而是因为他最中立、最有证据、最能落地。但&quot;最能落地&quot;不等于&quot;最能裁决&quot;——裁决权在共生法院，不在超脱者。超脱者是执行的手，不是判断的脑。手再强，也要听脑的。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./48-司法体系与裁决机制.html">48-司法体系与裁决机制</a> · <a href="./49-治理框架与权力制衡.html">49-治理框架与权力制衡</a> · <a href="./777_模块4-超脱者与万族-总论.html">777-超脱者与万族总论</a> · <a href="./780_模块4-万族-超脱者的监督机制.html">780-超脱者的监督机制</a></li><li>官网：<a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',27)])])}const d=o(e,[["render",i]]);export{q as __pageData,d as default};
